'use strict';
const P=window.PLAN;
const pages=[['index.html','Overview'],['tasks.html','Task register'],['documents.html','Document studio'],['checklists.html','Checklists'],['references.html','References'],['agencies.html','Agency directory'],['decisions.html','Decisions & records'],['sitemap.html','Site tree']];
const pagePath=location.pathname.replace(/\/+$/, '').split('/').pop()||'index';
const file=document.body.dataset.page||(pagePath.endsWith('.html')?pagePath:pagePath+'.html');
const docid=document.body.dataset.doc;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const unique=a=>[...new Set(a)];
let state={schema:1,tasks:{},checks:{}};let storageOK=true;
try{const s=JSON.parse(localStorage.getItem('seven-mile-admin-v1'));if(s&&s.schema===1&&s.tasks&&s.checks)state=s}catch{storageOK=false}
function persist(){try{localStorage.setItem('seven-mile-admin-v1',JSON.stringify(state))}catch{storageOK=false;announce('Storage is unavailable. Export your working notes before leaving.')}}
function announce(text){document.querySelector('#live').textContent=text}
function download(name,contents,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([contents],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
const status=t=>state.tasks[t.id]?.status||t.status;
const taskBy=id=>P.tasks.find(t=>t.id===id);
const sourceBy=id=>P.refs.find(r=>r.id===id);
const sourceLink=id=>{const r=sourceBy(id);return r?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a>`:''};
const docLink=id=>{const d=P.docs.find(d=>d.id===id);return d?`<a href="document-${id}.html">${id} · ${esc(d.title)}</a>`:''};
const pill=(t,c='')=>`<span class="pill ${c}">${esc(t)}</span>`;
const doneCount=()=>P.tasks.filter(t=>status(t)==='Done').length;
const localNotice=()=>`<aside class="notice">Working notes save in this browser${storageOK?'':' only while this page stays open'}. They do not update the public plan or another device. Export a backup to transfer them. Keep personal, financial and restricted cultural details in controlled records.</aside>`;
const fieldSelect=(id,label,values)=>`<label>${label}<select id="${id}"><option value="">All</option>${values.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`;
const searchBox=(placeholder)=>`<label class="search">Search<input id="query" type="search" placeholder="${esc(placeholder)}"></label>`;
function setupFilters(fn){['query','stream','phase','status','kind','level'].forEach(id=>document.getElementById(id)?.addEventListener('input',fn));fn()}
const query=()=>document.querySelector('#query')?.value.toLowerCase().trim()||'';
const matches=(item)=>JSON.stringify(item).toLowerCase().includes(query());
function paginate(items,card,container,limit=12){let page=0;function show(){const count=Math.max(1,Math.ceil(items.length/limit));page=Math.min(page,count-1);container.innerHTML=`<div class="results">${items.length} result${items.length===1?'':'s'}</div><div class="cards">${items.slice(page*limit,(page+1)*limit).map(card).join('')||'<p>No matching results. Try clearing a filter.</p>'}</div>${count>1?`<div class="pager"><button data-page="prev" ${page===0?'disabled':''}>Previous results</button><span>Page ${page+1} of ${count}</span><button data-page="next" ${page===count-1?'disabled':''}>Next results</button></div>`:''}`;container.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{page+=b.dataset.page==='next'?1:-1;show();container.scrollIntoView({block:'start',behavior:'smooth'})}));bindTasks(container)}show()}
function taskCard(t){const s=status(t);const blocked=t.depends.filter(id=>status(taskBy(id))!=='Done');return `<article class="card task"><div class="card-head">${pill(t.id)}${pill(t.stream)}${pill(s,s==='Done'?'good':'')}</div><h2>${esc(t.title)}</h2><p>${esc(t.acceptance)}</p><p class="meta">${esc(t.phase)} · ${docLink(t.document)}</p><details><summary>Inputs, owner and progress</summary><p>Dependencies: ${t.depends.map(id=>`<a href="tasks.html?task=${id}">${id}</a>`).join(', ')||'Start here'}${blocked.length?`<br>Open prerequisites: ${blocked.join(', ')}`:''}</p><label>Status<select data-status="${t.id}">${['To do','In progress','For review','Blocked','Done'].map(v=>`<option ${s===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Working owner<input data-owner="${t.id}" value="${esc(state.tasks[t.id]?.owner||t.owner)}" maxlength="160"></label><label>Non-sensitive working note<textarea data-note="${t.id}" maxlength="2000">${esc(state.tasks[t.id]?.note||'')}</textarea></label><p class="small">A working status is a personal note. Formal completion follows evidence, review and the appropriate decision.</p></details></article>`}
function bindTasks(container){container.querySelectorAll('[data-status],[data-owner],[data-note]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.status?'status':el.dataset.owner?'owner':'note';const id=el.dataset[k];state.tasks[id]={...state.tasks[id],[k]:el.value};persist();announce('Working note saved.');if(k==='status'){const progress=document.querySelector('#progress');if(progress)progress.textContent=`${doneCount()} / ${P.tasks.length} marked done in this browser`;const c=el.closest('article');if(c){const p=c.querySelector('.card-head').lastElementChild;p.textContent=el.value;p.classList.toggle('good',el.value==='Done')}}}))}
function docCard(d){return `<a class="card link-card" href="document-${d.id}.html"><div class="card-head">${pill(d.id)}${pill(d.group)}</div><h2>${esc(d.title)}</h2><p>${esc(d.purpose)}</p><span class="text-link">Inputs, checklist & AI prompt →</span></a>`}
function refCard(r){return `<article class="card"><div class="card-head">${pill(r.kind)}${pill(r.download?'Download link':'Source page')}</div><h2>${esc(r.title)}</h2><p>${esc(r.note)}</p><div class="actions"><a class="button secondary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Official/source page ↗</a>${r.download?`<a class="button" href="${esc(r.download)}" target="_blank" rel="noopener noreferrer">Download ${r.download.includes('xlsx')?'XLSX':r.download.includes('docx')?'DOCX':'PDF'} ↗</a>`:''}</div><p class="small">Located ${r.checked}. ${esc(r.verification)}. Use the source page if the download moves.</p></article>`}
const main=document.querySelector('#content');
function overview(){main.innerHTML=`<div class="metrics"><div><strong>2</strong><span>proposed entities</span></div><div><strong>${P.tasks.length}</strong><span>planning tasks</span></div><div><strong>${P.docs.length}</strong><span>document prompts</span></div><div><strong>${P.refs.length}</strong><span>source references</span></div></div><div class="intro-grid"><section><p class="eyebrow">THE WORKING ARRANGEMENT</p><h2>A shared purpose. Two clear vehicles.</h2><p>7-Mile is an Indigenous-led proposal for cultural activities, making, gardens, residencies and stays on Minjerribah. This workbench brings the establishment and operating preparation into one practical place.</p><p>The working structure pairs a member-controlled not-for-profit with an Indigenous-majority commercial entity. Legal forms, ownership arrangements and the cultural governance interface remain founding decisions.</p><div class="actions"><a class="button" href="tasks.html">Open the task register →</a><a class="button secondary" href="documents.html">Prepare a document</a></div></section><section class="dark-panel"><p class="eyebrow">FIRST USEFUL STEPS</p><ol><li>Record purposes, people and the two-entity choice.</li><li>Agree the cultural permission process.</li><li>Gather native title claim, boundary and permission records.</li><li>Prepare the rule book and company documents.</li><li>Develop cultural activities and stays as distinct operating plans.</li></ol><a href="checklists.html">Open the establishment checklists →</a></section></div><div class="cards compact"><article class="card"><h2>Community entity</h2><p>ORIC not-for-profit is the working option. Indigenous member control, board composition, purposes and charity eligibility are documented together.</p><a href="document-D04.html">Rule book preparation →</a></article><article class="card"><h2>Commercial entity</h2><p>A Pty Ltd working option with Indigenous-majority shares and votes. Direct ownership versus a community-entity subsidiary remains to be settled.</p><a href="document-D09.html">Ownership and control →</a></article><article class="card"><h2>Administration and training</h2><p>Ready Sustainable Employment and Training Cooperative is the proposed service interface. Legal identity, scope and employing responsibilities are recorded before contracting.</p><a href="document-D13.html">Service agreement preparation →</a></article></div><aside class="notice"><strong>C-Hours have no financial aspect.</strong> They recognise voluntary human contribution if participants choose to use them. They create no cash conversion, tradable value, wage substitute or financial claim.</aside><section><div class="section-head"><h2>Choose a starting point.</h2><a href="sitemap.html">See the site tree →</a></div><div class="cards compact">${[['documents.html','Document studio','Thirty briefs with inputs, checklists, review steps and copyable prompts.'],['references.html','Reference shelf','Official download links, rule book examples and business plan precedents.'],['agencies.html','Agency directory','Council, state and federal roles, with a useful question for each.']].map(([href,t,p])=>`<a href="${href}" class="card link-card"><h3>${t}</h3><p>${p}</p><span class="text-link">Open →</span></a>`).join('')}</div></section>`}
function tasks(){main.innerHTML=localNotice()+`<div class="toolbar">${searchBox('Task, evidence, document or keyword')}${fieldSelect('stream','Workstream',unique(P.tasks.map(t=>t.stream)))}${fieldSelect('phase','Phase',unique(P.tasks.map(t=>t.phase)))}${fieldSelect('status','Status',['To do','In progress','For review','Blocked','Done'])}</div><div class="actions"><a class="button secondary" href="tasks.csv" download>Download seeded tasks CSV</a><button id="export">Export working notes</button><label class="button secondary import">Import working notes<input type="file" id="import" accept="application/json,.json"></label><span id="progress" class="meta"></span></div><div id="results"></div>`;const target=new URLSearchParams(location.search).get('task');if(target)document.querySelector('#query').value=target;setupFilters(()=>{const rows=P.tasks.filter(t=>matches(t)&&(!document.querySelector('#stream').value||t.stream===document.querySelector('#stream').value)&&(!document.querySelector('#phase').value||t.phase===document.querySelector('#phase').value)&&(!document.querySelector('#status').value||status(t)===document.querySelector('#status').value));document.querySelector('#progress').textContent=`${doneCount()} / ${P.tasks.length} marked done in this browser`;paginate(rows,taskCard,document.querySelector('#results'))});document.querySelector('#export').onclick=()=>download('7-mile-working-notes.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2),'application/json');document.querySelector('#import').onchange=async e=>{try{const input=JSON.parse(await e.target.files[0].text());if(input.schema!==1||!input.tasks||typeof input.tasks!=='object'||!input.checks||typeof input.checks!=='object')throw Error('Wrong format');const clean={schema:1,tasks:{},checks:{}};for(const t of P.tasks){const r=input.tasks[t.id];if(r){if(r.status&&!['To do','In progress','For review','Blocked','Done'].includes(r.status))throw Error('Invalid status');clean.tasks[t.id]={status:r.status||'To do',owner:String(r.owner||t.owner).slice(0,160),note:String(r.note||'').slice(0,2000)}}}for(const [k,v] of Object.entries(input.checks)){if(/^D\d\d-[sr]-\d+$/.test(k)&&typeof v==='boolean')clean.checks[k]=v}state=clean;persist();tasks();announce('Working notes imported.')}catch{announce('Import failed. Choose a valid 7-Mile working-notes export.')} };}
function documents(){main.innerHTML=`<aside class="notice">These are document preparation briefs and AI prompts. Founding choices, review, adoption and lodgement remain visible tasks.</aside><div class="toolbar">${searchBox('Document, purpose or input')}${fieldSelect('stream','Workstream',unique(P.docs.map(d=>d.group)))}</div><div class="actions"><a class="button secondary" href="documents.csv" download>Download document register</a><a class="button secondary" href="plan.json" download>Download full planning data</a></div><div id="results"></div>`;setupFilters(()=>paginate(P.docs.filter(d=>matches(d)&&(!document.querySelector('#stream').value||d.group===document.querySelector('#stream').value)),docCard,document.querySelector('#results')))}
function documentDetail(d){main.innerHTML=`<div class="document-meta">${pill(d.id)}${pill(d.group)}${pill('To prepare')}<span>Working owner: ${esc(d.owner)}</span></div><p class="lead">${esc(d.purpose)}</p><div class="document-grid"><section><h2>Gather the inputs.</h2><ul>${d.inputs.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h2>Contents checklist</h2><p class="small">Ticks are working notes saved in this browser.</p>${d.sections.map((s,i)=>`<label class="check"><input type="checkbox" data-check="${d.id}-s-${i}" ${state.checks[`${d.id}-s-${i}`]?'checked':''}><span>${esc(s)}</span></label>`).join('')}<h2>Review checklist</h2>${d.checks.map((s,i)=>`<label class="check"><input type="checkbox" data-check="${d.id}-r-${i}" ${state.checks[`${d.id}-r-${i}`]?'checked':''}><span>${esc(s)}</span></label>`).join('')}</section><aside class="side-panel"><h2>Document trail</h2><p><strong>Prerequisites</strong></p>${d.depends.length?'<ul>'+d.depends.map(id=>'<li>'+docLink(id)+'</li>').join('')+'</ul>':'<p>Begin with the founding source and decision registers.</p>'}<p><strong>Related tasks</strong></p><ul>${P.tasks.filter(t=>t.document===d.id).map(t=>`<li><a href="tasks.html?task=${t.id}">${t.id} · ${esc(t.title)}</a></li>`).join('')}</ul><p><strong>Reference shelf</strong></p><ul>${d.sources.map(id=>`<li>${sourceLink(id)}</li>`).join('')}</ul><p class="small">Prepared → reviewed → adopted → signed/lodged where relevant. Each change needs its own evidence.</p></aside></div><section class="prompt-panel"><p class="eyebrow">AI MASTER PROMPT</p><h2>Prepare this document.</h2><p>Add non-sensitive confirmed inputs below, then copy or download the complete prompt. Attach private source records directly to an approved working session.</p><label>Optional confirmed inputs<textarea id="prompt-input" rows="4" placeholder="Agreed purposes, structure choices, evidence references and open questions..."></textarea></label><div class="actions"><button id="copy-prompt">Copy full prompt</button><button class="secondary" id="download-prompt">Download prompt TXT</button><a class="button secondary" href="prompts-${d.id}.txt" download>Download original prompt</a></div><details><summary>Read the full prompt</summary><pre id="prompt-text">${esc(d.prompt)}</pre></details></section><aside class="notice">Public versions include redacted purposes, task status and decisions approved for publication. Completed consents, IDs, signatures, sensitive finances and restricted cultural information remain in controlled records.</aside>`;main.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{state.checks[e.dataset.check]=e.checked;persist();announce('Checklist note saved.')});const full=()=>d.prompt+(document.querySelector('#prompt-input').value.trim()?'\nCONFIRMED INPUTS PROVIDED FOR THIS DRAFT:\n'+document.querySelector('#prompt-input').value.trim():'');document.querySelector('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(full());announce('Full prompt copied.');document.querySelector('#copy-prompt').textContent='Copied ✓'}catch{const p=document.querySelector('#prompt-text');p.textContent=full();p.parentElement.open=true;const selection=getSelection();const range=document.createRange();range.selectNodeContents(p);selection.removeAllRanges();selection.addRange(range);announce('Clipboard unavailable. The full prompt is selected for copying.')}};document.querySelector('#download-prompt').onclick=()=>download('7-mile-'+d.id+'-prompt.txt',full());}
function checklists(){main.innerHTML=localNotice()+`<div class="cards compact">${P.checklists.map(c=>`<a class="card link-card" href="checklists.html?list=${c.id}">${pill(c.id)}<h2>${esc(c.title)}</h2><p>${esc(c.note)}</p><span>${c.tasks.filter(id=>status(taskBy(id))==='Done').length} / ${c.tasks.length} working tasks complete →</span></a>`).join('')}</div><section id="checklist-detail"></section>`;const id=new URLSearchParams(location.search).get('list');const c=P.checklists.find(c=>c.id===id);if(c){document.querySelector('#checklist-detail').innerHTML=`<div class="section-head"><h2>${esc(c.title)}</h2><a href="checklists.html">All checklists</a></div><p>${esc(c.note)}</p><div class="cards">${c.tasks.map(id=>taskCard(taskBy(id))).join('')}</div>`;bindTasks(main);document.querySelector('#checklist-detail').scrollIntoView({block:'start'})}}
function references(){main.innerHTML=`<div class="toolbar">${searchBox('Rule book, plan, tourism or source')}${fieldSelect('kind','Reference type',unique(P.refs.map(r=>r.kind)))}</div><div class="actions"><a class="button secondary" href="references.csv" download>Download reference register</a></div><aside class="notice">Links point to source publishers. Binary links were located on official pages; this build has not inspected those downloads. Check structure, date and licence before reusing a precedent. The generic business plan template is adapted in separate cultural activity and accommodation prompts.</aside><div id="results"></div>`;setupFilters(()=>paginate(P.refs.filter(r=>matches(r)&&(!document.querySelector('#kind').value||r.kind===document.querySelector('#kind').value)),refCard,document.querySelector('#results')))}
function agencies(){main.innerHTML=`<aside class="notice">Redlands is the local government context; Oodgeroo and Bowman are electoral contexts. Questions go to the agency with the relevant remit. Prior political conversations do not replace written assessment responses.</aside><div class="toolbar">${searchBox('Agency, remit or question')}${fieldSelect('level','Government level',['Local','State','Federal'])}</div><div id="results"></div>`;setupFilters(()=>paginate(P.agencies.filter(a=>matches(a)&&(!document.querySelector('#level').value||a.level===document.querySelector('#level').value)),a=>`<article class="card"><div class="card-head">${pill(a.level)}${pill(a.type)}</div><h2>${esc(a.name)}</h2><p>${esc(a.role)}</p><h3>A useful question</h3><p>${esc(a.question)}</p>${sourceLink(a.source)}</article>`,document.querySelector('#results')))}
function decisions(){main.innerHTML=`<div class="cards compact"><article class="card"><h2>Already expressed</h2><ul><li>7-Mile is on a native title claim.</li><li>7-Mile has a not-for-profit and for-profit combination.</li><li>Indigenous majority and control are central to both.</li><li>Drafting and accounting setup are handled in-house.</li><li>QYAC-assisted document review is a possible pathway.</li><li>Ready S.E.T. Co-op is the proposed admin, employment and training interface.</li><li>C-Hours have no financial aspect.</li></ul></article><article class="card"><h2>Founding choices still open</h2><ul><li>Legal names and final legal forms.</li><li>Membership and cultural governance.</li><li>Direct shareholders or a community-entity subsidiary.</li><li>Share classes, votes, transfer and dilution protections.</li><li>Service scope, asset holders and benefit mechanism.</li><li>Document owners and agreed reviewers.</li></ul></article><article class="card"><h2>Evidence to gather</h2><ul><li>Native title claim reference, mapped area and authorised permissions.</li><li>Survey, current zoning, overlays and existing approvals.</li><li>Activity and stay capacity, durations and facilities.</li><li>Access, fire, water, waste and environmental requirements.</li><li>Demand, staffing, quotes and cash assumptions.</li><li>Actual registration and approval determinations.</li></ul></article></div><section><h2>Document version and review trail</h2><p>Use the document ID, version, date, owner, reviewer and adoption evidence in every working draft. The repository stores the public plan; completed private records remain with their authorised custodian.</p><div class="actions"><a class="button" href="document-D30.html">Prepare the decision register</a><a class="button secondary" href="document-D14.html">Prepare the review pack</a><a class="button secondary" href="document-D16.html">Prepare the accounting manual</a></div></section><section><h2>Supplied source pack</h2><p>The attached documents were read for context. Their role in this scoped build is recorded below. Their full contents have not been republished here.</p>${P.sourcefiles.map(s=>`<details class="source-row"><summary>${esc(s.title)} ${pill(s.role)}</summary><p>${esc(s.note)}</p></details>`).join('')}</section><section class="dark-panel"><h2>Public and private records</h2><p>The public hub holds task definitions, prompt briefs, references and approved public decisions. Private records hold signed consents, identity information, detailed cash records, confidential reviews and restricted cultural knowledge. AI use and publication follow the relevant permissions.</p><a href="document-D26.html">Prepare permissions and data rules →</a></section>`}
function sitemap(){main.innerHTML=`<p class="lead">Eight main destinations and thirty individual document pages. Choose a branch and open the next useful piece of work.</p><div class="tree-root"><a href="index.html">7-Mile planning & administration</a></div><div class="tree-grid">${pages.slice(1).map(([f,t])=>`<section class="tree-branch"><h2><a href="${f}">${t}</a></h2>${f==='documents.html'?unique(P.docs.map(d=>d.group)).map(g=>`<details><summary>${g}</summary><ul>${P.docs.filter(d=>d.group===g).map(d=>`<li>${docLink(d.id)}</li>`).join('')}</ul></details>`).join(''):f==='checklists.html'?'<ul>'+P.checklists.map(c=>`<li><a href="checklists.html?list=${c.id}">${esc(c.title)}</a></li>`).join('')+'</ul>':f==='references.html'?'<p>Templates · establishment · planning · tourism · examples · project references</p>':f==='agencies.html'?'<p>Local · state · federal. Statutory assessment, business support and industry development.</p>':f==='tasks.html'?'<p>Search tasks by stream, phase or working status. Inspect dependencies, owners and completion evidence.</p>':'<p>Founding choices, evidence gaps and the source trail.</p>'}</section>`).join('')}</div><section><h2>Download shelf</h2><div class="actions"><a href="tasks.csv" download>Tasks CSV</a><a href="documents.csv" download>Documents CSV</a><a href="references.csv" download>References CSV</a><a href="plan.json" download>Full plan JSON</a></div></section>`}
if(docid){documentDetail(P.docs.find(d=>d.id===docid))}else ({'index.html':overview,'tasks.html':tasks,'documents.html':documents,'checklists.html':checklists,'references.html':references,'agencies.html':agencies,'decisions.html':decisions,'sitemap.html':sitemap}[file]||overview)();
const order=docid?P.docs.map(d=>['document-'+d.id+'.html',d.id+' · '+d.title]):pages;
const current=order.findIndex(p=>p[0]===file);const prev=order[(current-1+order.length)%order.length];const next=order[(current+1)%order.length];
document.querySelector('#route-nav').innerHTML=`<a href="${prev[0]}"><small>← Previous</small><strong>${esc(prev[1])}</strong></a><a class="route-centre" href="${docid?'documents.html':'sitemap.html'}">${docid?'Document studio':'Site tree'}</a><a href="${next[0]}"><small>Next →</small><strong>${esc(next[1])}</strong></a>`;
document.querySelectorAll('.site-nav a').forEach(a=>{if(a.getAttribute('href')===(docid?'documents.html':file))a.setAttribute('aria-current','page')});
document.querySelector('#top-button').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
